import socket
import ipaddress
import urllib.request
import urllib.parse
import ssl
import json
import hashlib
import hmac
import time
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Optional, Tuple, Dict

# Configuration
ALLOWED_SCHEMES = ('http', 'https')
MAX_RESPONSE_SIZE = 1024 * 1024  # 1MB
REQUEST_TIMEOUT = 5


def _load_hmac_secret() -> bytes:
    """Load the HMAC secret from the environment.

    Fails closed: refuses to start with a predictable/hardcoded default so
    that audit signatures cannot be forged.
    """
    secret = os.environ.get('HMAC_SECRET')
    if not secret:
        raise RuntimeError(
            'HMAC_SECRET environment variable must be set to a strong, secret value.'
        )
    return secret.encode()


HMAC_SECRET = _load_hmac_secret()

# Internal network ranges that should never be accessed
BLOCKED_RANGES = [
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('169.254.0.0/16'),
    ipaddress.ip_network('::1/128'),
    ipaddress.ip_network('fc00::/7'),
    ipaddress.ip_network('fe80::/10'),
]


def _is_ip_blocked(ip_str: str) -> bool:
    """Check if an IP address falls within blocked ranges."""
    try:
        addr = ipaddress.ip_address(ip_str)
        for network in BLOCKED_RANGES:
            if addr in network:
                return True
        return False
    except ValueError:
        return True  # Block invalid IPs


def _validate_url_scheme(url: str) -> bool:
    """Ensure URL uses an allowed scheme."""
    parsed = urllib.parse.urlparse(url)
    return parsed.scheme in ALLOWED_SCHEMES


def _resolve_and_validate_host(hostname: str) -> Tuple[bool, Optional[str]]:
    """Resolve hostname and validate the IP is not in blocked ranges.

    Returns (is_safe, resolved_ip) tuple.
    Uses the system DNS resolver to check where the hostname points.
    """
    try:
        # Resolve all addresses for the hostname
        addr_infos = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM)

        if not addr_infos:
            return (False, None)

        # Check ALL resolved IPs - if any are blocked, reject
        resolved_ips = set()
        for family, socktype, proto, canonname, sockaddr in addr_infos:
            ip = sockaddr[0]
            resolved_ips.add(ip)
            if _is_ip_blocked(ip):
                return (False, None)

        # Return the first resolved IP for logging
        first_ip = next(iter(resolved_ips))
        return (True, first_ip)
    except (socket.gaierror, socket.herror, OSError):
        return (False, None)


def _generate_request_signature(url: str, timestamp: int) -> str:
    """Generate HMAC signature for request audit trail."""
    message = f"{url}|{timestamp}".encode()
    return hmac.new(HMAC_SECRET, message, hashlib.sha256).hexdigest()


def _verify_request_signature(url: str, timestamp: int, signature: str) -> bool:
    """Verify the HMAC signature of a request."""
    expected = _generate_request_signature(url, timestamp)
    return hmac.compare_digest(expected, signature)


class PinnedHTTPSHandler(urllib.request.HTTPSHandler):
    """Custom HTTPS handler that pins the connection to a specific IP."""

    def __init__(self, pinned_ip: str, *args, **kwargs):
        self._pinned_ip = pinned_ip
        super().__init__(*args, **kwargs)

    def https_open(self, req):
        return self.do_open(self._get_connection, req)

    def _get_connection(self, host, **kwargs):
        # Override connection to use pinned IP
        conn = super().https_open  # unused, just for structure
        return PinnedHTTPConnection(self._pinned_ip, host, **kwargs)


