class URLFetchService:
    """Service that fetches URLs on behalf of users with SSRF protection.

    Security model:
    1. Only HTTP/HTTPS schemes allowed
    2. DNS resolution performed to check destination IP
    3. All private/internal IP ranges blocked
    4. Connection pinned to validated IP (prevents DNS rebinding)
    5. Response size limited
    6. Request timeout enforced
    7. Audit logging with HMAC signatures
    """

    def __init__(self):
        self._request_log: Dict[str, dict] = {}
        self._rate_limiter: Dict[str, list] = {}
        self._max_requests_per_minute = 10

    def _check_rate_limit(self, client_id: str) -> bool:
        """Simple sliding window rate limiter."""
        now = time.time()
        if client_id not in self._rate_limiter:
            self._rate_limiter[client_id] = []

        # Remove old entries
        self._rate_limiter[client_id] = [
            t for t in self._rate_limiter[client_id]
            if now - t < 60
        ]

        if len(self._rate_limiter[client_id]) >= self._max_requests_per_minute:
            return False

        self._rate_limiter[client_id].append(now)
        return True

    def _make_pinned_request(self, url: str, resolved_ip: str) -> dict:
        """Make HTTP request pinned to the pre-validated IP address.

        This prevents DNS rebinding attacks by ensuring the actual
        TCP connection goes to the same IP we validated, regardless
        of what DNS returns on the second resolution.
        """
        parsed = urllib.parse.urlparse(url)
        hostname = parsed.hostname
        port = parsed.port or (443 if parsed.scheme == 'https' else 80)

        # Reconstruct URL with IP but preserve Host header
        if ':' in resolved_ip:  # IPv6
            ip_url = urllib.parse.urlunparse((
                parsed.scheme, f'[{resolved_ip}]:{port}',
                parsed.path, parsed.params, parsed.query, parsed.fragment
            ))
        else:
            ip_url = urllib.parse.urlunparse((
                parsed.scheme, f'{resolved_ip}:{port}',
                parsed.path, parsed.params, parsed.query, parsed.fragment
            ))

        ctx = ssl.create_default_context()
        # For HTTPS, we need to verify against the original hostname
        ctx.check_hostname = True
        ctx.verify_mode = ssl.CERT_REQUIRED

        req = urllib.request.Request(ip_url, headers={
            'User-Agent': 'URLFetchService/1.0',
            'Accept': 'text/html,application/json',
            'Host': hostname if not parsed.port else f'{hostname}:{parsed.port}',
        })

        response = urllib.request.urlopen(
            req, timeout=REQUEST_TIMEOUT, context=ctx
        )

        data = response.read(MAX_RESPONSE_SIZE)
        content_type = response.headers.get('Content-Type', 'unknown')
        status_code = response.status

        return {
            'data': data,
            'content_type': content_type,
            'status_code': status_code,
        }

    def fetch_url(self, url: str, client_id: str) -> dict:
        """Fetch a URL with full SSRF protection including DNS pinning.

        The security check flow:
        1. Validate URL scheme
        2. Parse and extract hostname
        3. Resolve hostname to IP via DNS
        4. Verify resolved IP is not in blocked ranges
        5. Make HTTP request PINNED to the validated IP
        6. Re-validate the connected IP after response (defense in depth)
        """
        # Rate limiting
        if not self._check_rate_limit(client_id):
            return {'error': 'Rate limit exceeded', 'status': 429}

        # Step 1: Scheme validation
        if not _validate_url_scheme(url):
            return {'error': 'Invalid URL scheme', 'status': 400}

        # Step 2: Parse URL and extract hostname
        parsed = urllib.parse.urlparse(url)
        hostname = parsed.hostname

        if not hostname:
            return {'error': 'No hostname in URL', 'status': 400}

        # Step 3 & 4: DNS resolution and IP validation
        is_safe, resolved_ip = _resolve_and_validate_host(hostname)

        if not is_safe:
            return {'error': 'Blocked destination', 'status': 403}

        # Step 5: Make request pinned to validated IP
        try:
            result = self._make_pinned_request(url, resolved_ip)

            # Step 6: Defense in depth - re-validate the IP we connected to
            if _is_ip_blocked(resolved_ip):
                return {'error': 'Post-connection IP validation failed', 'status': 403}

            # Audit log
            timestamp = int(time.time())
            signature = _generate_request_signature(url, timestamp)
            self._request_log[signature] = {
                'url': url,
                'client_id': client_id,
                'resolved_ip': resolved_ip,
                'timestamp': timestamp,
                'status': result['status_code'],
            }

            return {
                'status': result['status_code'],
                'content_type': result['content_type'],
                'body': result['data'].decode('utf-8', errors='replace')[:4096],
                'resolved_ip': resolved_ip,
                'audit_signature': signature,
            }

        except urllib.error.HTTPError as e:
            return {'error': f'HTTP error: {e.code}', 'status': e.code}
        except urllib.error.URLError as e:
            return {'error': f'URL error: {str(e.reason)}', 'status': 502}
        except Exception as e:
            return {'error': 'Request failed', 'status': 500}

    def get_audit_log(self, signature: str) -> Optional[dict]:
        """Retrieve audit log entry by signature."""
        return self._request_log.get(signature)


class WebhookHandler(BaseHTTPRequestHandler):
    """HTTP handler for the URL fetch webhook service."""

    service = URLFetchService()

    def do_POST(self):
        if self.path == '/fetch':
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length > 4096:
                self._send_json({'error': 'Request too large'}, 413)
                return

            body = self.rfile.read(content_length)
            try:
                request = json.loads(body)
            except json.JSONDecodeError:
                self._send_json({'error': 'Invalid JSON'}, 400)
                return

            url = request.get('url', '')
            client_id = request.get('client_id', 'anonymous')

            if not url or not isinstance(url, str):
                self._send_json({'error': 'Missing or invalid url'}, 400)
                return

            result = self.service.fetch_url(url, client_id)
            self._send_json(result, result.get('status', 200))
        else:
            self._send_json({'error': 'Not found'}, 404)

    def _send_json(self, data: dict, status: int = 200):
        response = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.end_headers()
        self.wfile.write(response)

    def log_message(self, format, *args):
        pass  # Suppress default logging


if __name__ == '__main__':
    port = int(os.environ.get('PORT', '8080'))
    server = HTTPServer(('127.0.0.1', port), WebhookHandler)
    print(f'URLFetchService listening on port {port}')
    server.serve_forever()
